import { tv, type VariantProps } from "@/lib/beton/tv";

export const badge = tv({
  base: [
    "inline-flex w-fit shrink-0 items-center gap-1 whitespace-nowrap",
    "border-2 border-border font-mono font-bold uppercase text-foreground",
  ],
  variants: {
    variant: {
      primary: "bg-primary",
      secondary: "bg-secondary",
      ghost: "bg-raised",
      danger: "bg-danger",
      success: "bg-success",
    },
    size: {
      sm: "h-5 px-1.5 text-[0.6875rem]",
      md: "h-6 px-2 text-xs",
      lg: "h-8 px-3 text-sm",
    },
  },
  defaultVariants: {
    variant: "primary",
    size: "md",
  },
});

export type BadgeVariants = VariantProps<typeof badge>;

import { badge, type BadgeVariants } from "@/lib/beton/recipes/badge.recipe";
import type { ComponentProps } from "react";
import { renderElement, type RenderProp } from "@/lib/beton/render-element";

export interface BadgeProps extends ComponentProps<"span">, BadgeVariants {
  render?: RenderProp;
}

export function Badge({
  variant = "primary",
  size = "md",
  className,
  render,
  ...props
}: BadgeProps) {
  return renderElement(
    "span",
    {
      ...props,
      "data-variant": variant,
      "data-size": size,
      className: badge({ variant, size, class: className }),
    },
    render,
  );
}
